HOT=SUB/"hotpath.py"
HOT.write_text('from __future__ import annotations\nfrom dataclasses import dataclass\nfrom queue import SimpleQueue, Empty\nfrom time import perf_counter_ns\nfrom typing import Callable\n\nMAX_ROUTE_AGE_MS=750.0\nDEFAULT_MIN_NET_BPS=20.0\nSIZES=(0.005,0.010,0.025,0.050,0.100,0.180,0.280,0.500,0.900,1.100,1.400)\n\n@dataclass(frozen=True)\nclass QuoteUpdate:\n    token:str\n    pump_pool:str\n    meteora_pool:str\n    venue:str\n    direction:str\n    size_sol:float\n    out_sol:float\n    observed_ns:int\n    sequence:int=0\n\n@dataclass(frozen=True)\nclass HotSignal:\n    token:str\n    pump_pool:str\n    meteora_pool:str\n    direction:str\n    size_sol:float\n    start_sol:float\n    end_sol:float\n    net_sol:float\n    net_bps:float\n    pump_age_ms:float\n    meteora_age_ms:float\n    route_age_ms:float\n    decision_us:float\n    execution_authority:bool=False\n\nclass HotBook:\n    def __init__(self,max_age_ms=MAX_ROUTE_AGE_MS,min_net_bps=DEFAULT_MIN_NET_BPS,clock_ns=perf_counter_ns):\n        self.max_age_ms=float(max_age_ms)\n        self.min_net_bps=float(min_net_bps)\n        self.clock_ns=clock_ns\n        self.pump={}\n        self.meteora={}\n        self.queue=SimpleQueue()\n        self.last_signal=None\n\n    def ingest(self,u:QuoteUpdate):\n        if u.venue=="PUMPSWAP":\n            self.pump[(u.token,u.pump_pool,u.meteora_pool,u.direction,float(u.size_sol))]=u\n        elif u.venue=="METEORA_DLMM":\n            self.meteora[(u.token,u.pump_pool,u.meteora_pool,u.direction,float(u.size_sol))]=u\n        else:\n            return None\n        return self._evaluate_key(u)\n\n    def publish(self,u:QuoteUpdate):\n        self.queue.put(u)\n\n    def drain_once(self):\n        try:u=self.queue.get_nowait()\n        except Empty:return None\n        return self.ingest(u)\n\n    def _evaluate_key(self,u):\n        t0=self.clock_ns()\n        k=(u.token,u.pump_pool,u.meteora_pool,u.direction,float(u.size_sol))\n        p=self.pump.get(k);m=self.meteora.get(k)\n        if p is None or m is None:return None\n        now=self.clock_ns()\n        p_age=max(0.0,(now-p.observed_ns)/1e6)\n        m_age=max(0.0,(now-m.observed_ns)/1e6)\n        age=max(p_age,m_age)\n        if age>self.max_age_ms:return None\n\n        start=float(u.size_sol)\n        if u.direction=="PUMP_TO_METEORA":\n            # Pump update expresses token bought per SOL; Meteora update expresses\n            # final SOL for that Pump token amount at this size.\n            end=float(m.out_sol)\n        elif u.direction=="METEORA_TO_PUMP":\n            end=float(p.out_sol)\n        else:\n            return None\n\n        net=end-start\n        bps=(net/start*10000.0) if start>0 else -1e18\n        if bps<self.min_net_bps:return None\n        decision_us=(self.clock_ns()-t0)/1e3\n        sig=HotSignal(\n            token=u.token,pump_pool=u.pump_pool,meteora_pool=u.meteora_pool,\n            direction=u.direction,size_sol=start,start_sol=start,end_sol=end,\n            net_sol=net,net_bps=bps,pump_age_ms=p_age,meteora_age_ms=m_age,\n            route_age_ms=age,decision_us=decision_us,execution_authority=False)\n        self.last_signal=sig\n        return sig\n\ndef from_snapshot_opportunity(op,observed_ns=None,sequence=0):\n    now=perf_counter_ns() if observed_ns is None else int(observed_ns)\n    token=op["token"];pump=op["pump_pool"];meta=op["meteora"]\n    direction=op["direction"];size=float(op["size_sol"])\n    end=(int(op["start"])+int(op["local_net"]))/1e9\n    # The hot book needs one update from each side. The upstream local snapshot\n    # already computed the full route; duplicate route-end on the receiving side\n    # only for deterministic handoff benchmarking. Live WebSocket binding replaces\n    # these with venue-native update events in the next boundary.\n    return (\n        QuoteUpdate(token,pump,meta["address"],"PUMPSWAP",direction,size,end,now,sequence),\n        QuoteUpdate(token,pump,meta["address"],"METEORA_DLMM",direction,size,end,now,sequence),\n    )\n\ndef hard_latency_gate(signal:HotSignal|None,max_age_ms=MAX_ROUTE_AGE_MS):\n    return bool(signal is not None and signal.route_age_ms<=float(max_age_ms))\n\ndef benchmark(iterations=5000):\n    book=HotBook()\n    now=book.clock_ns()\n    p=QuoteUpdate("T","P","M","PUMPSWAP","PUMP_TO_METEORA",0.05,0.054,now,1)\n    m=QuoteUpdate("T","P","M","METEORA_DLMM","PUMP_TO_METEORA",0.05,0.054,now,1)\n    book.ingest(p)\n    samples=[]\n    sig=None\n    for i in range(int(iterations)):\n        t=book.clock_ns()\n        m2=QuoteUpdate("T","P","M","METEORA_DLMM","PUMP_TO_METEORA",0.05,0.054,t,i+2)\n        s0=book.clock_ns()\n        sig=book.ingest(m2)\n        samples.append((book.clock_ns()-s0)/1e3)\n    samples.sort()\n    p50=samples[len(samples)//2]\n    p99=samples[min(len(samples)-1,int(len(samples)*0.99))]\n    return {"iterations":len(samples),"p50_us":p50,"p99_us":p99,\n            "signal":sig,"under_750ms":bool(sig and sig.route_age_ms<=750.0)}\n',encoding="utf-8")
py_compile.compile(str(HOT),doraise=True)

RT=SUB/"hotpath_runtime.py"
RT.write_text('from __future__ import annotations\nimport argparse,json,time\nfrom pathlib import Path\nfrom time import perf_counter_ns\nfrom qseries_v2.oracle_strategy_intelligence.solana_money.qarb_clean_bot import engine\nfrom qseries_v2.oracle_strategy_intelligence.solana_money.qarb_clean_bot.hotpath import HotBook,from_snapshot_opportunity,benchmark\n\ndef warm_once(root):\n    landing=engine.landing_cost_lamports()\n    universe=engine.candidate_universe(root)\n    book=HotBook(max_age_ms=750.0,min_net_bps=engine.MIN_NET_BPS)\n    warm=0;signals=[]\n    for x in universe:\n        try:\n            _,rows=engine.hydrate_and_rank_verified(x,landing)\n        except Exception:\n            continue\n        for op in rows[:3]:\n            if op["net_after_cost_bps"]<engine.MIN_NET_BPS:\n                continue\n            # convert the already-local quote result into an in-memory event handoff\n            raw={\n                "token":x["token"],"pump_pool":x["pump_pool"],\n                "meteora":x["meteora_meta"],"direction":op["direction"],\n                "size_sol":op["size_sol"],"start":op["start"],\n                "local_net":op["net_after_cost_lamports"],\n            }\n            a,b=from_snapshot_opportunity(raw,observed_ns=perf_counter_ns())\n            book.ingest(a)\n            sig=book.ingest(b)\n            warm+=1\n            if sig:signals.append(sig)\n    return book,warm,signals\n\ndef main(argv=None):\n    ap=argparse.ArgumentParser()\n    ap.add_argument("--benchmark",action="store_true")\n    ap.add_argument("--iterations",type=int,default=5000)\n    ap.add_argument("--once",action="store_true")\n    a=ap.parse_args(argv)\n\n    print("[QARB-004] SUB-750MS EVENT-DRIVEN IN-MEMORY HOT PATH",flush=True)\n    print("[CONTRACT] route_age<=750ms | no REST/RPC/filesystem inside HotBook.ingest()",flush=True)\n    print("[INTERLEG] atomic target => logical inter-leg gap 0ms",flush=True)\n    print("[MODE] scanner/handoff only | execution_authority=FALSE",flush=True)\n\n    if a.benchmark:\n        r=benchmark(a.iterations)\n        print("[BENCH] iterations=%d p50_us=%.2f p99_us=%.2f under_750ms=%s"%(\n            r["iterations"],r["p50_us"],r["p99_us"],r["under_750ms"]),flush=True)\n        return r\n\n    root=Path.cwd()\n    book,warm,signals=warm_once(root)\n    print("[WARM] local_positive_routes=%d hot_signals=%d"%(warm,len(signals)),flush=True)\n    if signals:\n        best=max(signals,key=lambda s:s.net_sol)\n        print("[HOT_SIGNAL] token=%s dir=%s size=%.6f net=%+.9f SOL bps=%+.2f age_ms=%.3f decision_us=%.2f"%(\n            best.token,best.direction,best.size_sol,best.net_sol,best.net_bps,\n            best.route_age_ms,best.decision_us),flush=True)\n    else:\n        print("[HOT_SIGNAL] NONE",flush=True)\n    print("[NEXT] bind existing Solana WebSocket account/program updates directly into HotBook.publish/ingest",flush=True)\n    return {"warm":warm,"signals":len(signals)}\n\nif __name__=="__main__":\n    main()\n',encoding="utf-8")
py_compile.compile(str(RT),doraise=True)

TEST=ROOT/"test_qarb_004_sub750_event_driven_hotpath.py"
TEST.write_text('import inspect,time,unittest\nfrom time import perf_counter_ns\nfrom qseries_v2.oracle_strategy_intelligence.solana_money.qarb_clean_bot.hotpath import *\n\nclass T(unittest.TestCase):\n    def test_profitable_signal_under_750ms(self):\n        b=HotBook(max_age_ms=750,min_net_bps=20)\n        now=perf_counter_ns()\n        self.assertIsNone(b.ingest(QuoteUpdate("T","P","M","PUMPSWAP","PUMP_TO_METEORA",.05,.054,now,1)))\n        s=b.ingest(QuoteUpdate("T","P","M","METEORA_DLMM","PUMP_TO_METEORA",.05,.054,now,1))\n        self.assertIsNotNone(s)\n        self.assertGreater(s.net_bps,20)\n        self.assertLessEqual(s.route_age_ms,750)\n        print("[PASS] fresh Pump->Meteora positive event produces sub-750ms hot signal")\n\n    def test_stale_route_hard_rejected(self):\n        b=HotBook(max_age_ms=750,min_net_bps=20)\n        old=perf_counter_ns()-800_000_000\n        b.ingest(QuoteUpdate("T","P","M","PUMPSWAP","PUMP_TO_METEORA",.05,.054,old,1))\n        s=b.ingest(QuoteUpdate("T","P","M","METEORA_DLMM","PUMP_TO_METEORA",.05,.054,perf_counter_ns(),2))\n        self.assertIsNone(s)\n        print("[PASS] >750ms route age hard rejected")\n\n    def test_reverse_direction(self):\n        b=HotBook()\n        now=perf_counter_ns()\n        b.ingest(QuoteUpdate("T","P","M","METEORA_DLMM","METEORA_TO_PUMP",.05,.054,now,1))\n        s=b.ingest(QuoteUpdate("T","P","M","PUMPSWAP","METEORA_TO_PUMP",.05,.054,now,1))\n        self.assertIsNotNone(s)\n        print("[PASS] reverse Meteora->Pump hot signal supported")\n\n    def test_no_network_or_filesystem_in_hot_ingest(self):\n        src=inspect.getsource(HotBook.ingest)+inspect.getsource(HotBook._evaluate_key)\n        low=src.lower()\n        for bad in ("urllib","requests","rpc(","open(","path(","sleep(","subprocess"):\n            self.assertNotIn(bad,low)\n        print("[PASS] HotBook ingest/evaluate has zero network/filesystem/sleep calls")\n\n    def test_queue_event_path(self):\n        b=HotBook()\n        now=perf_counter_ns()\n        b.publish(QuoteUpdate("T","P","M","PUMPSWAP","PUMP_TO_METEORA",.05,.054,now,1))\n        self.assertIsNone(b.drain_once())\n        b.publish(QuoteUpdate("T","P","M","METEORA_DLMM","PUMP_TO_METEORA",.05,.054,now,2))\n        self.assertIsNotNone(b.drain_once())\n        print("[PASS] event queue -> in-memory route decision works")\n\n    def test_latency_benchmark(self):\n        r=benchmark(3000)\n        self.assertTrue(r["under_750ms"])\n        self.assertLess(r["p99_us"],750000)\n        print("[PASS] deterministic hot-path benchmark p99_us=%.2f"%r["p99_us"])\n\nif __name__=="__main__":\n    unittest.main(verbosity=2)\n',encoding="utf-8")
py_compile.compile(str(TEST),doraise=True)

